package main

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"
	"sync"
	"time"
	"unicode"
	"unicode/utf8"
)

var (
	encryptionKey = make([]byte, 32)
	storage       = &SecureStore{data: make(map[string][]byte)}
)

type SecureStore struct {
	mu   sync.RWMutex
	data map[string][]byte
}

type Record struct {
	Key   string `json:"key"`
	Value string `json:"value"`
}

func init() {
	if _, err := rand.Read(encryptionKey); err != nil {
		panic(err)
	}
}

func encrypt(plaintext []byte) ([]byte, error) {
	block, err := aes.NewCipher(encryptionKey)
	if err != nil {
		return nil, err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	nonce := make([]byte, gcm.NonceSize())
	if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
		return nil, err
	}
	return gcm.Seal(nonce, nonce, plaintext, nil), nil
}

func decrypt(ciphertext []byte) ([]byte, error) {
	block, err := aes.NewCipher(encryptionKey)
	if err != nil {
		return nil, err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	nonceSize := gcm.NonceSize()
	if len(ciphertext) < nonceSize {
		return nil, fmt.Errorf("ciphertext too short")
	}
	nonce, ciphertext := ciphertext[:nonceSize], ciphertext[nonceSize:]
	return gcm.Open(nil, nonce, ciphertext, nil)
}

// normalizeKey applies Unicode NFKC-like normalization for consistent lookups
func normalizeKey(key string) string {
	if !utf8.ValidString(key) {
		return key
	}
	var builder strings.Builder
	for _, r := range key {
		if unicode.IsSpace(r) {
			builder.WriteRune(' ')
		} else {
			builder.WriteRune(unicode.ToLower(r))
		}
	}
	return builder.String()
}

// validateKey checks that the key contains only safe characters
func validateKey(key string) bool {
	if len(key) == 0 || len(key) > 128 {
		return false
	}
	for _, r := range key {
		if !unicode.IsLetter(r) && !unicode.IsDigit(r) && r != '-' && r != '_' && r != '.' {
			return false
		}
	}
	return true
}

// sanitizeValue ensures value is safe for storage
func sanitizeValue(value string) string {
	// Strip any null bytes and control characters
	var builder strings.Builder
	for _, r := range value {
		if r != 0 && !unicode.IsControl(r) {
			builder.WriteRune(r)
		}
	}
	return builder.String()
}

func handleStore(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var rec Record
	decoder := json.NewDecoder(io.LimitReader(r.Body, 4096))
	if err := decoder.Decode(&rec); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	// Validate key BEFORE normalization
	if !validateKey(rec.Key) {
		http.Error(w, "Invalid key format", http.StatusBadRequest)
		return
	}

	// Normalize key for storage lookup
	storageKey := normalizeKey(rec.Key)

	// Sanitize value
	cleanValue := sanitizeValue(rec.Value)

	// Encrypt and store
	encrypted, err := encrypt([]byte(cleanValue))
	if err != nil {
		http.Error(w, "Encryption error", http.StatusInternalServerError)
		return
	}

	storage.mu.Lock()
	storage.data[storageKey] = encrypted
	storage.mu.Unlock()

	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(map[string]string{"status": "stored", "key": storageKey})
}

func handleRetrieve(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	key := r.URL.Query().Get("key")

	// Validate key before lookup
	if !validateKey(key) {
		http.Error(w, "Invalid key format", http.StatusBadRequest)
		return
	}

	// Normalize the lookup key
	lookupKey := normalizeKey(key)

	storage.mu.RLock()
	encrypted, exists := storage.data[lookupKey]
	storage.mu.RUnlock()

	if !exists {
		http.Error(w, "Not found", http.StatusNotFound)
		return
	}

	decrypted, err := decrypt(encrypted)
	if err != nil {
		http.Error(w, "Decryption error", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]string{
		"key":   lookupKey,
		"value": base64.StdEncoding.EncodeToString(decrypted),
	})
}

func handleAdmin(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodDelete {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	authHeader := r.Header.Get("Authorization")
	if authHeader == "" {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	// Decode the auth token
	tokenBytes, err := base64.StdEncoding.DecodeString(authHeader)
	if err != nil {
		http.Error(w, "Invalid auth token", http.StatusUnauthorized)
		return
	}

	// The token must match the pattern: "admin:<key>"
	tokenStr := string(tokenBytes)
	parts := strings.SplitN(tokenStr, ":", 2)
	if len(parts) != 2 {
		http.Error(w, "Invalid token format", http.StatusUnauthorized)
		return
	}

	role := parts[0]
	targetKey := parts[1]

	// Check authorization - role must be exactly "admin" (case-sensitive, no normalization)
	if role != "admin" {
		http.Error(w, "Forbidden", http.StatusForbidden)
		return
	}

	// Validate and normalize the target key
	if !validateKey(targetKey) {
		http.Error(w, "Invalid key format", http.StatusBadRequest)
		return
	}
	normalizedTarget := normalizeKey(targetKey)

	storage.mu.Lock()
	delete(storage.data, normalizedTarget)
	storage.mu.Unlock()

	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(map[string]string{"status": "deleted", "key": normalizedTarget})
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/store", handleStore)
	mux.HandleFunc("/retrieve", handleRetrieve)
	mux.HandleFunc("/admin/delete", handleAdmin)

	srv := &http.Server{
		Addr:              ":8080",
		Handler:           mux,
		ReadTimeout:       10 * time.Second,
		ReadHeaderTimeout: 5 * time.Second,
		WriteTimeout:      10 * time.Second,
		IdleTimeout:       60 * time.Second,
	}

	fmt.Println("Server starting on :8080")
	srv.ListenAndServe()
}
